396	        }
397	        Duration interval = Duration.between(previous.testedAt(), latest.testedAt());
398	        if (interval.compareTo(Duration.ofHours(DIACETYL_MIN_INTERVAL_HOURS)) < 0) {
399	            throw ApiException.unprocessable("双乙酰两次采样间隔不足 12 小时，不允许降温");
400	        }
401	    }
