package com.example.starter.fermentation.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 合成清酒接收罐台账。
 *
 * @param id             接收罐 ID
 * @param tankCode       接收罐编号，全局唯一
 * @param capacityLiters 容量，单位升，正数最多三位小数；不得缩到已接收量以下
 * @param receivedLiters 已接收清酒总量，单位升，等于各合批接收单合计
 * @param version        台账版本号，从 1 开始，每次成功变更（调容或接收）加 1
 * @param createdAt      登记时间（UTC）
 */
public record ReceivingTank(
        long id,
        String tankCode,
        BigDecimal capacityLiters,
        BigDecimal receivedLiters,
        int version,
        LocalDateTime createdAt) {
}

package com.example.starter.fermentation.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 源批实际清酒升数台账。登记一次后冻结，启用一次核销管控
 * （旧单笔转出与合批接收共享唯一核销，先到者消费）。
 *
 * @param id           台账记录 ID
 * @param batchId      源批次 ID，每批仅登记一次
 * @param volumeLiters 实际清酒升数，单位升，正数最多三位小数且不超过源发酵罐容量
 * @param version      台账版本号，从 1 开始；登记后冻结不再变更
 * @param createdAt    登记时间（UTC）
 */
public record SourceVolume(
        long id,
        long batchId,
        BigDecimal volumeLiters,
        int version,
        LocalDateTime createdAt) {
}

package com.example.starter.fermentation.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 合批接收单：一次接收 2 至 5 个受控源批进入同一接收罐，原子核销。
 *
 * @param id               接收单 ID
 * @param receivingTankId  接收罐 ID
 * @param curveCode        全部来源统一的工艺曲线编码
 * @param curveVersion     全部来源统一的工艺曲线版本号
 * @param totalLiters      本次接收合计升数，等于各来源登记量之和
 * @param receivedAt       接收受理业务时间（由调用方传入）
 * @param createdAt        接收单创建时间（UTC）
 */
public record MergeReceipt(
        long id,
        long receivingTankId,
        String curveCode,
        int curveVersion,
        BigDecimal totalLiters,
        LocalDateTime receivedAt,
        LocalDateTime createdAt) {
}

package com.example.starter.fermentation.domain;

import java.math.BigDecimal;

/**
 * 合批接收来源明细：完整接收该源批登记量，不做部分转出。
 *
 * @param id           明细 ID
 * @param receiptId    所属合批接收单 ID
 * @param batchId      来源批次 ID
 * @param volumeLiters 该来源完整接收的登记升数
 */
public record MergeReceiptSource(
        long id,
        long receiptId,
        long batchId,
        BigDecimal volumeLiters) {
}

