                .getResponse().getStatus());
        assertEquals(200, cooling(id, newRequestId(), T0.plusHours(14))
                .getResponse().getStatus());
        assertEquals(200, startMaturation(id, newRequestId(), T0.plusHours(15))
                .getResponse().getStatus());
        return id;
    }

