/**
 * 合批接收功能测试：接收罐登记与调容、源批实际升数台账、合批接收主流程与失败分支、
 * 容量恰满、坏一源回滚、版本失配、升数勾稽与幂等重放。
 */
class MergeReceiptTest extends BaseFermentationTest {

    private static final LocalDateTime RECEIVE_AT = T0.plusDays(9);

    @Test
